			saveDefaultLayout: _tableLayoutInfo.privSaveGlobally
				? async () => {
						if (_tableLayoutInfo.moduleName !== "") {
							await saveDefaultLayoutForAgency(
								_tableLayoutInfo.moduleName,
								_tableObject.getConfiguration()
							);
						}
				  }
				: null,
			exportTable: onExport
