					")</small>";
				break;
			case ModuleNameEnum.CEHEADER:
				text +=
					CETITLE +
					" " +
					_parentTableSelection.cehe_bookid +
					"/" +
					_parentTableSelection.cehe_headerid +
					" - Var. " +
					_parentTableSelection.cehe_variantid;
