function countSubstringOccurrences(string, substring) {
	if (substring.length === 0) {
		return 0;
	}

	let count = 0;
	let index = 0;

	while (index !== -1) {
		index = string.indexOf(substring, index);

		if (index !== -1) {
			count++;
			index += substring.length;
		}
	}

	return count;
}

